import React from "react";
import { useParams, useNavigate } from "react-router-dom";
import products from "../data/products";
import { useCart } from "../context/CartContext";

// Toast
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { addToCart } = useCart();

  const product = products.find((p) => p.id === parseInt(id));

  if (!product)
    return <h2 style={{ textAlign: "center" }}>Product Not Found</h2>;

  // ================= CART =================
  const handleAddToCart = () => {
    addToCart(product);
    toast.success("Added to cart 🛒");
  };

  // ================= BUY NOW (IMPORTANT FIX) =================
  const handleBuyNow = () => {
    localStorage.setItem("buyProduct", JSON.stringify(product));

    console.log("BUY PRODUCT SAVED:", product); // DEBUG

    navigate("/checkout");
  };

  return (
    <div
      style={{
        padding: "60px 20px",
        minHeight: "100vh",
        background: "linear-gradient(135deg, #fff1f8, #f0fbff)",
      }}
    >
      <div
        style={{
          maxWidth: "1100px",
          margin: "auto",
          display: "flex",
          gap: "60px",
          flexWrap: "wrap",
          alignItems: "center",
          background: "white",
          padding: "35px",
          borderRadius: "25px",
          boxShadow: "0 20px 50px rgba(0,0,0,0.1)",
        }}
      >
        {/* IMAGE */}
        <div style={{ flex: "1" }}>
          <img
            src={product.image}
            alt={product.name}
            style={{
              width: "100%",
              borderRadius: "20px",
            }}
          />
        </div>

        {/* DETAILS */}
        <div style={{ flex: "1" }}>
          <h1 style={{ color: "#d63384", fontSize: "32px" }}>
            {product.name}
          </h1>

          <p
            style={{
              fontSize: "22px",
              fontWeight: "600",
              color: "#ff4f87",
            }}
          >
            ₹{product.price}
          </p>

          <p>Age: {product.age || "Not specified"}</p>

          <p style={{ color: "#444", marginTop: "10px" }}>
            This beautiful handmade product is made with love 💖
          </p>

          {/* BUTTONS */}
          <button
            onClick={handleAddToCart}
            style={btn}
          >
            Add to Cart 🛒
          </button>

          <button
            onClick={handleBuyNow}
            style={{ ...btn, background: "#28a745", marginLeft: "10px" }}
          >
            Buy Now ⚡
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;

// ================= STYLE =================
const btn = {
  marginTop: "30px",
  padding: "14px 25px",
  border: "none",
  borderRadius: "30px",
  background: "linear-gradient(135deg, #ff4f87, #ff85a2)",
  color: "white",
  fontSize: "16px",
  cursor: "pointer",
  fontWeight: "600",
};
